// Формирует текст Telegram-сообщения из payload outbox.
// Webhook-node кладёт POST body в $json.body — берём его как корень.
// Если event_type не из списка — возвращает пусто и Telegram skip'ается.
// app_base_url приходит из cfg.AppBaseURL воркера, link на конкретный
// проект — /manager/projects/{id} (не /admin/board?p=...).
//
// ВАЖНО: набор веток ниже обязан совпадать с таблицей назначения в
// internal/eventroute/chat.go (пометка ToChat). Их сверяет тест
// TestWorkflowHandlesExactlyChatEvents: ветка default молча выбрасывает
// событие, отвечая приложению 200, и потерю иначе не заметить.
// Правило отбора там же: в чат идёт только то, на что нужно ответить
// человеком и чего он иначе не увидит вовремя.
const raw = $input.first().json;
const e = raw.body || raw;
const t = e.event_type;
const d = e.data || {};

// Markdown-escape для динамических полей (заголовок, имя, контакт).
const esc = (s) => String(s ?? '').replace(/([_*`])/g, '\\$1');
const title = esc(d.title || '(без названия)');
const clientName = esc(d.client_name || '—');
const clientContact = esc(d.client_contact || '');
const spec = esc(d.specialist_display_name || '—');
const budget = d.budget ? `${d.budget} ₽` : '';
const reason = esc(d.reason || '');

const projectId = d.project_id || e.aggregate_id;
const app = e.app_base_url || '';
const link = (projectId && app)
  ? `\n[Открыть в CRM](${app}/manager/projects/${projectId})`
  : '';

const fmtClient = clientContact ? `${clientName} (${clientContact})` : clientName;

// Короткий id — для событий подбора: пока заказ не превратился в
// проект, отличить один от другого в чате больше нечем.
const shortId = (v) => String(v ?? '').slice(0, 8);
// Ссылка у событий подбора появляется, только когда у заказа уже есть
// проект: подбор идёт до оплаты, а проект заводят после неё. Собирать
// адрес из номера заказа нельзя — он ведёт в никуда.
const orderLink = (d.project_id && app)
  ? `\n[Открыть в CRM](${app}/manager/projects/${d.project_id})`
  : '';
const dueDate = esc(d.due_date || '');

let text;
switch (t) {
  case 'project.created':
    text = `🆕 *Новый бриф*\n*${title}*` +
           `\nКлиент: ${fmtClient}` +
           (budget ? `\nБюджет: ${budget}` : '') +
           link;
    break;
  case 'project.specialist_assigned':
    text = `👤 *Назначен специалист*\n*${title}*` +
           `\nКлиент: ${fmtClient}` +
           `\nСпециалист: ${spec}` +
           link;
    break;
  case 'project.specialist_approved':
    text = `✅ *Менеджер одобрил специалиста*\n*${title}*` +
           `\nСпециалист: ${spec}` +
           link;
    break;
  case 'project.assigned':
    text = `👨‍💼 *Менеджер взял в работу*\n*${title}*` +
           `\nКлиент: ${fmtClient}` +
           (d.manager_display_name ? `\nМенеджер: ${esc(d.manager_display_name)}` : '') +
           link;
    break;
  case 'project.comment_added': {
    const body = esc(d.body || '').slice(0, 500);
    text = `💬 *Новый комментарий*\n*${title}*` +
           `\n${body}` +
           link;
    break;
  }
  case 'moderation.specialist_pending': {
    // Спец встал в очередь модерации (publish_requested — впервые/после reject;
    // content_changed — был approved, поменял профиль). См.
    // docs/SPECIALIST_MODERATION.md. Ссылка ведёт на админку.
    const userId = d.user_id || e.aggregate_id;
    const displayName = esc(d.display_name || '—');
    const email = esc(d.email || '');
    const why = d.reason === 'content_changed'
      ? 'изменения после одобрения'
      : 'первая публикация / повторная попытка';
    const modLink = (userId && app)
      ? `\n[Открыть карточку](${app}/admin/moderation/${userId})`
      : '';
    text = `🔍 *Новая заявка на модерацию*\n*${displayName}*` +
           (email ? `\n${email}` : '') +
           `\nПричина: ${why}` +
           modLink;
    break;
  }
  case 'project.specialist_rejected':
    // Половина истории хуже, чем никакой: чат сообщал «клиент выбрал» и
    // «менеджер подтвердил» — и молчал там, где подтверждения не будет.
    text = `🚫 *Менеджер отклонил специалиста*\n*${title}*` +
           `\nСпециалист: ${spec}` +
           (reason ? `\nПричина: ${reason}` : '') +
           `\nНужно предложить клиенту другого` +
           link;
    break;
  case 'project.disputed':
    text = `⚠️ *Спор по проекту*\n*${title}*` +
           `\nКлиент: ${fmtClient}` +
           `\nРабота остановлена — ответьте клиенту` +
           link;
    break;
  case 'project.general_created':
    text = `🆕 *Разовый заказ*\n*${title}*` +
           `\nКлиент: ${fmtClient}` +
           (spec !== '—' ? `\nИсполнитель: ${spec}` : '') +
           (dueDate ? `\nСрок: ${dueDate}` : '') +
           link;
    break;
  case 'project.publication_overdue': {
    // Напоминание креатору ушло ему лично; в чат — потому что срок уже
    // сорван, и дальше это вопрос к менеджеру.
    const days = Number(d.days_overdue || 0);
    const projectTitle = esc(d.project_title || title);
    text = `⏰ *Просрочена выкладка*\n*${projectTitle}*` +
           (dueDate ? `\nСрок был ${dueDate}` : '') +
           (days > 0 ? ` · просрочка ${days} дн.` : '') +
           `\nКреатор не выложил — нужен менеджер` +
           link;
    break;
  }
  case 'project.manager_digest': {
    // Сводка «что горит сегодня» — она ровно для чата и задумана.
    const projectTitle = esc(d.project_title || title);
    const parts = [];
    if (Number(d.due_today || 0) > 0) parts.push(`сегодня ${Number(d.due_today)}`);
    if (Number(d.overdue || 0) > 0) parts.push(`просрочено ${Number(d.overdue)}`);
    if (Number(d.incomplete || 0) > 0) parts.push(`неполных ${Number(d.incomplete)}`);
    if (parts.length === 0) return [];
    text = `📋 *Сводка по проекту*\n*${projectTitle}*` +
           `\nВыкладки: ${parts.join(' · ')}` +
           link;
    break;
  }
  case 'project.period_closed': {
    // Период подытожен: просмотры заморожены срезом, счёт посчитан.
    // Приблизительный срез говорим прямо — число, которому не на что
    // опереться, не должно выглядеть как остальные.
    const seq = Number(d.period_seq || 0);
    const span = (d.starts_on && d.ends_on)
      ? `${esc(d.starts_on)} — ${esc(d.ends_on)}`
      : '';
    const videos = Number(d.videos || 0);
    const views = Number(d.views || 0);
    const total = Number(d.total || 0);
    const rub = (kop) => (kop / 100).toLocaleString('ru-RU');
    text = `🧾 *Период подытожен*\n*${title}*` +
           (seq > 0 ? `\nПериод ${seq}` : '') + (span ? ` · ${span}` : '') +
           `\nРоликов: ${videos} · просмотров: ${views.toLocaleString('ru-RU')}` +
           `\nК оплате клиенту: ${rub(total)} ₽` +
           (d.snapshot_approx
             ? `\n⚠️ Данные приблизительные: поденная статистика за период уже удалена`
             : '') +
           link;
    break;
  }
  case 'order.need_more':
    text = `🙋 *Заказ некем закрыть*` +
           `\nЗаказ \`${shortId(d.order_id || e.aggregate_id)}\`` +
           (Number(d.need_more || 0) > 0 ? `\nНе хватает: ${Number(d.need_more)}` : '') +
           `\nРезерв кончился — добрать креаторов вручную` +
           orderLink;
    break;
  case 'order.candidate_silent':
    text = `🔕 *Креатор не отвечает сутки*` +
           `\nЗаказ \`${shortId(d.order_id || e.aggregate_id)}\`` +
           ` · креатор \`${shortId(d.creator_id)}\`` +
           `\nМесто занято и не двигается — позвать другого` +
           orderLink;
    break;
  default:
    return [];
}
return [{ json: { text } }];
